      faqs: [
        { q: 'ನನಗೆ ಕೋಡಿಂಗ್ ಗೊತ್ತಿರಬೇಕೇ?', a: 'ಇಲ್ಲ. ನೀವು ನಿಮ್ಮ ಆ್ಯಪ್ ಅನ್ನು ಸರಳ ಇಂಗ್ಲಿಷ್‌ನಲ್ಲಿ ವಿವರಿಸುತ್ತೀರಿ ಮತ್ತು WyberAi ಎಲ್ಲಾ ಕೋಡ್ ಅನ್ನು ರಚಿಸುತ್ತದೆ. ಒಂದೇ ಫೈಲ್ ಅನ್ನೂ ಮುಟ್ಟದೆ ನಿಮ್ಮ ಫೋನ್‌ನಲ್ಲಿ ಪ್ರಿವ್ಯೂ ನೋಡಬಹುದು.' },
        { q: 'ಮೊಬೈಲ್‌ಗಾಗಿ WyberAi ಯಾವ ಟೆಕ್ ಸ್ಟ್ಯಾಕ್ ಬಳಸುತ್ತದೆ?', a: 'WyberAi Expo SDK 52 ಬಳಸಿ React Native ಪ್ರಾಜೆಕ್ಟ್‌ಗಳನ್ನು ರಚಿಸುತ್ತದೆ. ಇದು Shopify, Discord, ಮತ್ತು Meta ನಂತಹ ಕಂಪನಿಗಳು ಬಳಸುವ ಇಂಡಸ್ಟ್ರಿ-ಸ್ಟ್ಯಾಂಡರ್ಡ್ ಸ್ಟ್ಯಾಕ್ ಆಗಿದೆ.' },
        { q: 'ನಾನು App Store ಗೆ ಪ್ರಕಟಿಸಬಹುದೇ?', a: 'ಹೌದು. ನಿಮ್ಮ ಪ್ರಾಜೆಕ್ಟ್ ಅನ್ನು ಎಕ್ಸ್‌ಪೋರ್ಟ್ ಮಾಡಿ ಮತ್ತು Expo Application Services (EAS Build) ಬಳಸಿ IPA ಅಥವಾ APK ರಚಿಸಿ App Store ಅಥವಾ Google Play ಗೆ ಸಲ್ಲಿಸಿ.' },
        { q: 'ಮೊಬೈಲ್ ಆ್ಯಪ್ ರಚಿಸಲು ಎಷ್ಟು ಸಮಯ ತೆಗೆದುಕೊಳ್ಳುತ್ತದೆ?', a: 'ಹೆಚ್ಚಿನ ಆ್ಯಪ್‌ಗಳು ನಿಮಿಷಗಳಲ್ಲಿ ರಚನೆಯಾಗುತ್ತವೆ. ಸಂಕೀರ್ಣ ಬಹು-ಸ್ಕ್ರೀನ್ ಆ್ಯಪ್‌ಗಳಿಗೆ 90–120 ಸೆಕೆಂಡುಗಳು ಬೇಕಾಗಬಹುದು. ಕೋಡ್ ರಿಯಲ್ ಟೈಮ್‌ನಲ್ಲಿ ಸ್ಟ್ರೀಮ್ ಆಗುವುದನ್ನು ನೀವು ನೋಡುತ್ತೀರಿ.' },
        { q: 'ಆರಂಭಿಕ ರಚನೆಯ ನಂತರ ಇನ್ನಷ್ಟು ಸ್ಕ್ರೀನ್‌ಗಳನ್ನು ಸೇರಿಸಬಹುದೇ?', a: 'ಹೌದು. ಚಾಟ್‌ನಲ್ಲಿ ಹೊಸ ಸ್ಕ್ರೀನ್ ಅನ್ನು ವಿವರಿಸಿ: "ಪ್ರೊಫೈಲ್ ಎಡಿಟರ್ ಮತ್ತು ನೋಟಿಫಿಕೇಶನ್ ಟಾಗಲ್‌ಗಳಿರುವ Settings ಸ್ಕ್ರೀನ್ ಸೇರಿಸಿ." WyberAi ಇದನ್ನು ಪೂರ್ಣ ನ್ಯಾವಿಗೇಶನ್ ಜೋಡಣೆಯೊಂದಿಗೆ ಸೇರಿಸುತ್ತದೆ.' },
      ],
